import type { ICommonUser, ICooperativeData, IVars } from '../../model'
import type { IGenerate, IMetaDocument } from '../../document'

export const registry_id = 1053

// Модель действия для генерации
export interface Action extends IGenerate {
  registry_id: number
  debt_hash: string
  amount: string
  due_at: string
  basis_type: 'uhd' | 'offer'
  program_name?: string
  collateral: string
}

export type Meta = IMetaDocument & Action

// Модель данных документа
export interface Model {
  meta: IMetaDocument
  coop: ICooperativeData
  vars: IVars
  user: ICommonUser
  short_hash: string
  basis_title_dative: string
  basis_title_genitive: string
  basis_title_instrumental: string
  basis_number: string
  basis_date: string
  amount_digits: string
  due_at: string
  collateral_program_dative: string
}

export const title = "Договор о беспроцентном займе под обеспечение паевым взносом"
export const description = "Договор между кооперативом и пайщиком о беспроцентном займе, обеспеченном правом пайщика на возврат части паевого взноса в целевой потребительской программе"

export const context = "<div class=\"digital-document\"><div style=\"text-align: right\"><p>ПРИЛОЖЕНИЕ № {{short_hash}}</p><p>к {{basis_title_dative}} № {{basis_number}} от {{basis_date}}</p></div><h2 style=\"text-align: center\">ДОГОВОР о беспроцентном займе</h2><p>{{coop.city}}, {{created_at}}</p><p>{{vars.full_abbr}} «{{vars.name}}» в лице Председателя Совета {{coop.chairman.last_name}} {{coop.chairman.first_name}} {{coop.chairman.middle_name}}, действующего на основании Устава, (далее — Общество) и {{user.full_name_or_short_name}} (далее — Пайщик), совместно именуемые Стороны, заключили настоящий Договор о беспроцентном займе (далее — Договор) о нижеследующем.</p><h3>1. Предмет Договора</h3><p>1.1. Настоящий Договор заключён в соответствии с Уставом и положениями Общества и {{basis_title_instrumental}} № {{basis_number}} от {{basis_date}} .</p><p>1.2. Общество предоставляет Пайщику заём денежными средствами в сумме {{amount_digits}} (далее — Сумма займа), а Пайщик обязуется вернуть Сумму займа в срок и в порядке, которые предусмотрены настоящим Договором.</p><p>1.3. Обеспечением возврата Суммы займа является право требования Пайщика к Обществу о возврате части его паевого взноса по {{collateral_program_dative}} в размере Суммы займа (далее — Обеспечение). На срок действия настоящего Договора часть паевого взноса в размере Суммы займа учитывается Обществом обособленно и в расчётах по программе не участвует.</p><p>1.4. Пайщик не уплачивает Обществу проценты за пользование займом (пункт 1 статьи 809 Гражданского кодекса Российской Федерации, далее — ГК РФ).</p><h3>2. Порядок передачи и возврата Суммы займа</h3><p>2.1. Общество предоставляет Сумму займа перечислением денежных средств по реквизитам, указанным Пайщиком в его личном кабинете в информационной системе Общества (далее — Личный кабинет).</p><p>2.2. Сумма займа считается предоставленной Пайщику с даты зачисления денежных средств на счёт Пайщика по реквизитам, указанным в Личном кабинете (пункт 5 статьи 807 ГК РФ).</p><p>2.3. Пайщик возвращает Сумму займа в полном размере не позднее {{due_at}}.</p><p>2.4. Пайщик возвращает Сумму займа одним из следующих способов:</p><p>2.4.1. зачислением денежных средств на расчётный счёт Общества либо распоряжением о возврате из средств своего паевого взноса в Личном кабинете с указанием реквизитов настоящего Договора;</p><p>2.4.2. прекращением обязательства зачётом встречного требования Пайщика о возврате части паевого взноса, составляющей Обеспечение (статья 410 ГК РФ).</p><p>2.5. Заём считается возвращённым в момент поступления соответствующей суммы денежных средств на расчётный счёт Общества либо в момент проведения зачёта согласно подпункту 2.4.2 настоящего Договора (пункт 3 статьи 810 ГК РФ).</p><p>2.6. Сумма займа может быть возвращена досрочно полностью или по частям (пункт 2 статьи 810 ГК РФ). При частичном возврате Обеспечение уменьшается на возвращённую сумму.</p><p>2.7. Срок возврата Суммы займа может быть продлён по заявлению Пайщика с согласия Общества. Новый срок указывается в заявлении, подписанном Пайщиком и Председателем Совета Общества в Личном кабинете.</p><p>2.8. Общество вправе отказаться от исполнения настоящего Договора полностью или частично при наличии обстоятельств, очевидно свидетельствующих о том, что предоставленный Пайщику заём не будет возвращён в срок (пункт 3 статьи 807 ГК РФ).</p><h3>3. Ответственность Сторон</h3><p>3.1. В случае невозврата Суммы займа в срок, установленный пунктом 2.3 настоящего Договора, Общество вправе:</p><p>3.1.1. требовать с Пайщика уплаты процентов в порядке, предусмотренном пунктом 1 статьи 811 и пунктом 1 статьи 395 ГК РФ;</p><p>3.1.2. прекратить обязательство Пайщика по возврату Суммы займа зачётом встречного требования Пайщика о возврате части паевого взноса, составляющей Обеспечение (статья 410 ГК РФ).</p><p>3.2. При наступлении обстоятельств, указанных в пункте 3.1 настоящего Договора, Общество уведомляет Пайщика в Личном кабинете о неисполнении обязательства. Если в течение 5 (пяти) дней с даты уведомления Стороны не согласовали способ и срок возврата Суммы займа, Общество проводит зачёт согласно подпункту 3.1.2 настоящего Договора и уведомляет Пайщика о проведённом зачёте в Личном кабинете.</p><p>3.3. Уплата процентов в соответствии с законодательством Российской Федерации не освобождает Пайщика от исполнения обязательства в натуре.</p><p>3.4. В иных случаях неисполнения обязательств по настоящему Договору Стороны несут ответственность согласно законодательству Российской Федерации.</p><h3>4. Обстоятельства непреодолимой силы</h3><p>4.1. Стороны освобождаются от ответственности за неисполнение или ненадлежащее исполнение обязательств по настоящему Договору вследствие обстоятельств непреодолимой силы, то есть чрезвычайных и непредотвратимых при данных условиях обстоятельств (пункт 3 статьи 401 ГК РФ), в том числе запретительных действий органов власти, гражданских волнений, эпидемий, блокады, эмбарго, землетрясений, наводнений, пожаров и других стихийных бедствий.</p><p>4.2. При наступлении обстоятельств, предусмотренных пунктом 4.1 настоящего Договора, срок исполнения обязательств по настоящему Договору приостанавливается на время действия этих обстоятельств.</p><h3>5. Заключительные положения</h3><p>5.1. Настоящий Договор заключён в электронной форме и подписан Сторонами электронной подписью в порядке, установленном Положением об электронной подписи Общества. Договор вступает в силу с момента его подписания Председателем Совета Общества.</p><p>5.2. Уведомления по настоящему Договору направляются Сторонами через Личный кабинет и считаются доставленными в момент размещения в нём (статья 165.1 ГК РФ).</p><p>5.3. Изменения и дополнения к настоящему Договору оформляются соглашением Сторон, подписанным электронной подписью в Личном кабинете; продление срока возврата оформляется в порядке пункта 2.7 настоящего Договора.</p><p>5.4. Споры по настоящему Договору разрешаются в суде по месту нахождения Общества в соответствии с законодательством Российской Федерации.</p><h3>6. Реквизиты и подписи Сторон</h3><p>Общество: {{vars.full_abbr}} «{{vars.name}}», ИНН {{coop.details.inn}}, КПП {{coop.details.kpp}}, ОГРН {{coop.details.ogrn}}, адрес: {{coop.full_address}}, телефон: {{coop.phone}}, электронная почта: {{coop.email}}, расчётный счёт {{coop.defaultBankAccount.account_number}} в {{coop.defaultBankAccount.bank_name}}, БИК {{coop.defaultBankAccount.details.bik}}, корреспондентский счёт {{coop.defaultBankAccount.details.corr}}.</p><p>Председатель Совета {{coop.chairman.last_name}} {{coop.chairman.first_name}} {{coop.chairman.middle_name}}. Подписано электронной подписью.</p><p>Пайщик: {{user.full_name_or_short_name}}, телефон: {{user.phone}}, электронная почта: {{user.email}}. Подписано электронной подписью.</p></div><style>.digital-document {padding: 20px;white-space: pre-wrap;} .digital-document p {margin: 0 0 8px 0;} .digital-document h3 {margin: 16px 0 8px 0;}</style>"

